mapper.insert:
INSERT INTO TB_CALENDAR_SHARE (
    CALENDAR_ID, SHARE_TYPE, USERNAME, SHARED_BY, CREATED_BY
) VALUES (
    #{calendarId}, #{shareType}, #{username}, #{sharedBy}, #{createdBy}
