mapper.update:
UPDATE TB_CALENDAR_SHARE
SET DELETED_AT = NOW(), UPDATED_BY = #{deletedBy}
WHERE CALENDAR_ID = #{calendarId}
  AND USERNAME = #{username}
  AND DELETED_AT IS NULL

